// Initialize company processing session
const folderName = $node["Google Drive Trigger"].json.name;
const folderId = $node["Google Drive Trigger"].json.id;

// Generate unique company ID
const companyId = `company_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

// Clean company name
let companyName = folderName || 'Unknown_Company';
companyName = companyName
  .replace(/^(new folder|folder|untitled|document)$/i, 'Unknown_Company')
  .replace(/[_-]+/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

if (companyName.length < 2) {
  companyName = 'Unknown_Company';
}

console.log('🏢 STARTING DUE DILIGENCE PROCESS');
console.log('═'.repeat(60));
console.log(`📁 Company Folder: ${folderName}`);
console.log(`🏢 Company Name: ${companyName}`);
console.log(`🆔 Company ID: ${companyId}`);
console.log(`📂 Folder ID: ${folderId}`);
console.log('═'.repeat(60));

return {
  json: {
    company_id: companyId,
    company_name: companyName,
    company_folder_name: folderName,
    company_folder_id: folderId,
    processing_status: 'initialized',
    start_time: new Date().toISOString(),
    current_step: 'ingestion'
  }
};

// Process PDF list and create ingestion items
const companyInfo = $node["Initialize Company Processing"].json;
const response = $input.first().json;

const files = (response && response.files) ? response.files : [];

if (!files || !Array.isArray(files) || files.length === 0) {
  console.log('❌ No PDF files found in company folder');
  return {
    json: {
      ...companyInfo,
      error: 'No PDF files found',
      processing_status: 'no_files_found'
    }
  };
}

console.log(`📄 Found ${files.length} PDF files for ingestion`);
files.forEach((file, index) => {
  console.log(`  ${index + 1}. ${file.name} (${file.size} bytes)`);
});

// Return each file as separate item for parallel processing
return files.map((file, index) => ({
  json: {
    ...companyInfo,
    file_id: file.id,
    file_name: file.name,
    file_size: file.size,
    file_index: index,
    total_files: files.length,
    processing_status: 'ready_for_ingestion'
  }
}));

// Combine all PDF texts into one comprehensive document
const allInputs = $input.all();
const firstInput = allInputs[0]?.json;

// Extract company information safely
const companyInfo = firstInput?.company_info || firstInput;
const companyName = companyInfo?.company_name || 'Unknown Company';
const companyId = companyInfo?.company_id || 'unknown_company';

console.log('📋 COMBINING ALL PDF CONTENT');
console.log('═'.repeat(50));
console.log(`🏢 Company: ${companyName}`);
console.log(`📄 Processing ${allInputs.length} extracted PDF texts`);

// Combine all PDF content
let combinedContent = '';
const fileContents = [];

allInputs.forEach((input, index) => {
  if (input.json) {
    const extractedData = input.json;
    const fileInfo = input.json.company_info || input.json;

    let fileText = '';
    if (extractedData.data) {
      fileText = extractedData.data;
    } else if (typeof extractedData === 'string') {
      fileText = extractedData;
    }

    if (fileText && fileText.length > 100) {
      const fileName = fileInfo?.file_name || `Document_${index + 1}`;
      fileContents.push({
        file_name: fileName,
        content: fileText,
        length: fileText.length
      });

      // Add to combined content with clear separation
      combinedContent += `\n\n=== DOCUMENT: ${fileName} ===\n\n`;
      combinedContent += fileText;
      combinedContent += `\n\n=== END OF ${fileName} ===\n\n`;

      console.log(`📄 Added: ${fileName} (${fileText.length} chars)`);
    }
  }
});

console.log(`📊 Combined Content Stats:`);
console.log(`  • Total files: ${fileContents.length}`);
console.log(`  • Combined length: ${combinedContent.length} characters`);
console.log(`  • Average per file: ${Math.round(combinedContent.length / fileContents.length)} chars`);
console.log('═'.repeat(50));

return {
  json: {
    company_id: companyId,
    company_name: companyName,
    company_folder_name: companyInfo?.company_folder_name || companyName,
    company_folder_id: companyInfo?.company_folder_id,
    start_time: companyInfo?.start_time,
    combined_pdf_content: combinedContent,
    individual_files: fileContents,
    total_files: fileContents.length,
    total_content_length: combinedContent.length,
    processing_status: 'content_combined',
    combined_at: new Date().toISOString()
  }
};

// Create text chunks with unique IDs for Pinecone
const extractedData = $input.first().json;
const fileInfo = $node["Prepare PDF Ingestion"].json;

console.log(`📄 Processing chunks for: ${fileInfo.file_name}`);

// Get extracted text
let fullText = '';
if (extractedData && extractedData.data) {
  fullText = extractedData.data;
} else if (typeof extractedData === 'string') {
  fullText = extractedData;
}

if (!fullText || fullText.length < 100) {
  console.error(`❌ Text extraction failed for ${fileInfo.file_name}`);
  return [{
    json: {
      ...fileInfo,
      error: 'Text extraction failed',
      processing_status: 'extraction_failed'
    }
  }];
}

// Create chunks with unique IDs
const chunkSize = 1000;
const overlap = 200;
const chunks = [];
const timestamp = Date.now();

for (let i = 0; i < fullText.length; i += (chunkSize - overlap)) {
  const chunk = fullText.substring(i, i + chunkSize);
  if (chunk.trim().length > 50) {
    // Create unique chunk ID: originalFileName + "_" + chunkIndex + "_" + timestamp
    const chunkId = `${fileInfo.file_name.replace(/[^a-zA-Z0-9]/g, '_')}_${chunks.length}_${timestamp}`;

    chunks.push({
      id: chunkId,
      content: chunk.trim(),
      metadata: {
        company_id: fileInfo.company_id,
        company_name: fileInfo.company_name,
        file_name: fileInfo.file_name,
        file_id: fileInfo.file_id,
        chunk_index: chunks.length,
        total_chunks_this_file: Math.ceil(fullText.length / (chunkSize - overlap)),
        extracted_at: new Date().toISOString(),
        source_type: 'factual_pdf'
      }
    });
  }
}

console.log(`📦 Created ${chunks.length} chunks for ${fileInfo.file_name}`);

// Return all chunks for this file
return chunks.map(chunk => ({
  json: {
    id: chunk.id,
    pageContent: chunk.content,
    metadata: chunk.metadata,
    company_info: fileInfo
  }
}));

// Aggregate ingestion results and prepare for section processing
const allInputs = $input.all();

// Safe extraction of company info
let companyInfo;
if (allInputs && allInputs.length > 0 && allInputs[0].json && allInputs[0].json.company_info) {
  companyInfo = allInputs[0].json.company_info;
} else if (allInputs && allInputs.length > 0 && allInputs[0].json) {
  // Fallback: try to extract from first input directly
  companyInfo = allInputs[0].json;
} else {
  console.error('❌ No company info found in inputs');
  return {
    json: {
      error: 'No company information available',
      processing_status: 'failed'
    }
  };
}

// Safe extraction of company name with fallbacks
const companyName = companyInfo?.company_name || companyInfo?.name || 'Unknown Company';
const companyId = companyInfo?.company_id || 'unknown_company';

console.log('📊 INGESTION COMPLETE');
console.log('═'.repeat(50));
console.log(`🏢 Company: ${companyName}`);
console.log(`🆔 Company ID: ${companyId}`);

// Count chunks by file
const fileChunkCounts = {};
let totalChunks = 0;
let allTextContent = ''; // Combine all PDF text

allInputs.forEach(input => {
  if (input.json && input.json.metadata) {
    const fileName = input.json.metadata.file_name;
    if (!fileChunkCounts[fileName]) {
      fileChunkCounts[fileName] = 0;
    }
    fileChunkCounts[fileName]++;
    totalChunks++;

    // Combine all text content
    if (input.json.pageContent) {
      allTextContent += input.json.pageContent + '\n\n';
    }
  }
});

console.log(`📦 Total Chunks Ingested: ${totalChunks}`);
console.log('📄 Files Processed:');
Object.entries(fileChunkCounts).forEach(([fileName, count]) => {
  console.log(`  • ${fileName}: ${count} chunks`);
});
console.log(`📝 Combined content length: ${allTextContent.length} characters`);
console.log('═'.repeat(50));

return {
  json: {
    company_id: companyId,
    company_name: companyName,
    company_folder_name: companyInfo?.company_folder_name || companyName,
    company_folder_id: companyInfo?.company_folder_id || companyInfo?.folder_id,
    combined_pdf_content: allTextContent, // All PDF content combined
    ingestion_complete: true,
    total_chunks_ingested: totalChunks,
    files_processed: Object.keys(fileChunkCounts).length,
    chunk_counts_by_file: fileChunkCounts,
    processing_status: 'ready_for_sections',
    current_step: 'section_generation',
    ingestion_completed_at: new Date().toISOString(),
    start_time: companyInfo?.start_time || new Date().toISOString()
  }
};

// Collect all section outputs and prepare for PDF generation
const allSections = $input.all();
const companyInfo = $node["Complete Ingestion"].json;

console.log('📋 COLLECTING SECTION OUTPUTS');
console.log('═'.repeat(50));

// Safe extraction of company information
const companyName = companyInfo?.company_name || 'Unknown Company';
const companyId = companyInfo?.company_id || 'unknown_company';

const sectionResults = [];
let approvedSections = 0;
let failedSections = 0;

// Process only the sections we actually have
if (allSections && allSections.length > 0) {
  allSections.forEach((sectionOutput, index) => {
    const sectionNumber = index + 1;
    const sectionData = sectionOutput?.json;

    if (sectionData && sectionData.status === 'approved' && sectionData.content) {
      sectionResults.push({
        section_number: sectionNumber,
        title: sectionData.title || sectionData.section_title || `Section ${sectionNumber}`,
        content: sectionData.content,
        status: 'approved',
        word_count: sectionData.content.length,
        generated_at: sectionData.approved_at || sectionData.generated_at || new Date().toISOString()
      });
      approvedSections++;
      console.log(`✅ Section ${sectionNumber}: ${sectionData.title || sectionData.section_title || 'Untitled'} (${sectionData.content.length} chars)`);
    } else {
      sectionResults.push({
        section_number: sectionNumber,
        title: `Section ${sectionNumber} - FAILED`,
        content: 'ERROR: Section generation failed or was not approved.',
        status: 'failed',
        error: sectionData?.error || 'Unknown error'
      });
      failedSections++;
      console.log(`❌ Section ${sectionNumber}: FAILED - ${sectionData?.error || 'Unknown error'}`);
    }
  });
} else {
  console.log('⚠️ No section outputs received');
  sectionResults.push({
    section_number: 1,
    title: 'No Sections Generated',
    content: 'No section outputs were received from the section workflows.',
    status: 'failed',
    error: 'No section outputs'
  });
  failedSections = 1;
}

const totalSections = sectionResults.length;
const successRate = totalSections > 0 ? ((approvedSections / totalSections) * 100).toFixed(1) : '0.0';

console.log('═'.repeat(50));
console.log(`✅ Approved Sections: ${approvedSections}/${totalSections}`);
console.log(`❌ Failed Sections: ${failedSections}/${totalSections}`);
console.log(`📊 Success Rate: ${successRate}%`);
console.log('═'.repeat(50));

return {
  json: {
    company_id: companyId,
    company_name: companyName,
    company_folder_name: companyInfo?.company_folder_name || companyName,
    company_folder_id: companyInfo?.company_folder_id,
    start_time: companyInfo?.start_time,
    ingestion_completed_at: companyInfo?.ingestion_completed_at,
    files_processed: companyInfo?.files_processed || 0,
    total_chunks_ingested: companyInfo?.total_chunks_ingested || 0,
    sections: sectionResults,
    total_sections: totalSections,
    approved_sections: approvedSections,
    failed_sections: failedSections,
    success_rate: `${successRate}%`,
    processing_status: 'ready_for_pdf_generation',
    current_step: 'pdf_generation',
    sections_completed_at: new Date().toISOString()
  }
};

// Generate final PDF content from all approved sections
const data = $input.first().json;

console.log('📄 GENERATING FINAL PDF');
console.log('═'.repeat(50));

// Create PDF content structure
let pdfContent = '';

// Add title page
pdfContent += `# Due Diligence Report\n\n`;
pdfContent += `**Company:** ${data.company_name}\n\n`;
pdfContent += `**Generated:** ${new Date().toLocaleDateString()}\n\n`;
pdfContent += `**Sections Completed:** ${data.approved_sections}/20 (${data.success_rate})\n\n`;
pdfContent += `**Total Files Analyzed:** ${data.files_processed}\n\n`;
pdfContent += `**Knowledge Base Chunks:** ${data.total_chunks_ingested}\n\n`;
pdfContent += `---\n\n`;

// Add table of contents
pdfContent += `## Table of Contents\n\n`;
data.sections.forEach(section => {
  pdfContent += `${section.section_number}. ${section.title}\n`;
});
pdfContent += `\n---\n\n`;

// Add all sections
data.sections.forEach(section => {
  pdfContent += `## ${section.section_number}. ${section.title}\n\n`;
  pdfContent += `${section.content}\n\n`;

  if (section.status === 'failed') {
    pdfContent += `*Note: This section could not be generated due to: ${section.error}*\n\n`;
  }

  pdfContent += `---\n\n`;
});

// Add generation metadata
pdfContent += `## Generation Metadata\n\n`;
pdfContent += `- **Company ID:** ${data.company_id}\n`;
pdfContent += `- **Processing Started:** ${data.start_time}\n`;
pdfContent += `- **Ingestion Completed:** ${data.ingestion_completed_at}\n`;
pdfContent += `- **Sections Completed:** ${data.sections_completed_at}\n`;
pdfContent += `- **PDF Generated:** ${new Date().toISOString()}\n`;
pdfContent += `- **Total Processing Time:** ${Math.round((new Date() - new Date(data.start_time)) / 1000 / 60)} minutes\n`;

console.log(`📊 PDF Content Generated: ${pdfContent.length} characters`);
console.log(`📄 Sections Included: ${data.sections.length}`);
console.log('═'.repeat(50));

return {
  json: {
    ...data,
    pdf_content: pdfContent,
    pdf_file_name: `Due_Diligence_Report_${data.company_name.replace(/[^a-zA-Z0-9]/g, '_')}_${new Date().toISOString().split('T')[0]}.md`,
    processing_status: 'pdf_content_ready',
    pdf_generated_at: new Date().toISOString()
  }
};

// Final completion status and summary
const reportData = $node["Generate PDF Content"].json;
const uploadData = $node["Upload Final Report"].json;
const dbData = $input.first().json;

const processingTimeMinutes = Math.round((new Date() - new Date(reportData.start_time)) / 1000 / 60);

console.log('🎉 DUE DILIGENCE PROCESS COMPLETE!');
console.log('═'.repeat(60));
console.log(`🏢 Company: ${reportData.company_name}`);
console.log(`📁 Company Folder: ${reportData.company_folder_name}`);
console.log(`📄 Files Processed: ${reportData.files_processed}`);
console.log(`📦 Knowledge Chunks: ${reportData.total_chunks_ingested}`);
console.log(`📋 Sections Generated: ${reportData.approved_sections}/20`);
console.log(`✅ Success Rate: ${reportData.success_rate}`);
console.log(`⏱️ Total Processing Time: ${processingTimeMinutes} minutes`);
console.log(`📄 Final Report: ${uploadData.name}`);
console.log(`🔗 Report URL: ${uploadData.webViewLink}`);
console.log('═'.repeat(60));

return {
  json: {
    processing_complete: true,
    company_id: reportData.company_id,
    company_name: reportData.company_name,
    final_status: 'success',
    summary: {
      files_processed: reportData.files_processed,
      chunks_ingested: reportData.total_chunks_ingested,
      sections_generated: `${reportData.approved_sections}/20`,
      success_rate: reportData.success_rate,
      processing_time_minutes: processingTimeMinutes
    },
    final_report: {
      file_name: uploadData.name,
      file_id: uploadData.id,
      download_url: uploadData.webViewLink,
      folder_id: reportData.company_folder_id
    },
    completed_at: new Date().toISOString(),
    status_message: `✅ Due diligence report generated successfully for ${reportData.company_name}`
  }
};
